UPDATE `maa_tnews`
SET 
    `ctitle` = 'PORTFOLIO PATHWAY PROGRAM',
    `eng_ctitle` = 'PORTFOLIO PATHWAY PROGRAM',
    `ccode` = 'portfolio-pathway-program',
    `cshort_content` = '<h6>Độ tuổi: 15–18 <span class=\"lo_trinh_label\">Lộ trình cá nhân hoá</span></h6>\r\n\r\n<div class=\"bt_bb_inner_step_text\">\r\n<p><b>Pre-Portfolio &amp; International Portfolio Development</b></p>\r\n<p>Portfolio Pathway Programme do MAA – Magic Arts &amp; Architecture Education phát triển, là lộ trình giáo dục chuyên biệt dành cho học sinh từ 15–18 tuổi có định hướng theo đuổi các ngành sáng tạo tại các trường đại học tại Đức, Châu Âu và Châu Á.</p>\r\n\r\n<p><b>Hai giai đoạn đào tạo:</b></p>\r\n<ul>\r\n\t<li><b>01 | Pre-Portfolio (15–16 tuổi):</b> Nền tảng Sáng tạo &amp; Khám phá (Creative Foundation &amp; Exploration).</li>\r\n\t<li><b>02 | Portfolio Development (17–18 tuổi):</b> Xây dựng Portfolio Quốc tế &amp; Chuẩn bị Đại học (International Creative Portfolio &amp; University Preparation).</li>\r\n</ul>\r\n</div>',
    
    `eng_cshort_content` = '<h6>Ages: 15–18 <span class=\"lo_trinh_label\">Personalised Pathway</span></h6>\r\n\r\n<div class=\"bt_bb_inner_step_text\">\r\n<p><b>Pre-Portfolio &amp; International Portfolio Development</b></p>\r\n<p>The Portfolio Pathway Programme, developed by MAA – Magic Arts &amp; Architecture Education, is a specialised educational pathway for students aged 15–18 who aspire to pursue creative disciplines at universities in Germany, across Europe and Asia.</p>\r\n\r\n<p><b>Two Stages:</b></p>\r\n<ul>\r\n\t<li><b>01 | Pre-Portfolio (Ages 15–16):</b> Creative Foundation &amp; Exploration.</li>\r\n\t<li><b>02 | Portfolio Development (Ages 17–18):</b> International Creative Portfolio &amp; University Preparation.</li>\r\n</ul>\r\n</div>',
    
    `ccontent` = '<p style=\"text-align:center; margin-bottom: 25px;\">\r\n\t<img src=\"/fileman/Uploads/programs/pd1.jpg\" alt=\"PORTFOLIO PATHWAY PROGRAM\" style=\"max-width:100%; height:auto; border-radius: 6px; box-shadow: 0 4px 15px rgba(0,0,0,0.1); margin: 0 auto; display: block;\">\r\n</p>\r\n\r\n<div class=\"program-detail-header\" style=\"margin-bottom: 25px; border-bottom: 2px solid #FFCB00; padding-bottom: 15px;\">\r\n\t<h2 style=\"color: #191919; margin-bottom: 5px; font-weight: 700;\">PORTFOLIO PATHWAY PROGRAMME</h2>\r\n\t<h4 style=\"color: #555; font-weight: 600; margin-bottom: 8px;\">Pre-Portfolio &amp; International Portfolio Development</h4>\r\n\t<p style=\"color: #777; font-size: 15px; margin-bottom: 8px;\"><strong>Ages 15–18</strong> | Personalised Creative Education Pathway</p>\r\n\t<p style=\"font-weight: 700; color: #d39e00; letter-spacing: 0.5px; text-transform: uppercase;\">YOUR DREAM DEGREE. YOUR INDIVIDUAL PORTFOLIO.</p>\r\n</div>\r\n\r\n<h4 style=\"color: #191919;\">Discover Your Potential. Develop Your Creative Identity.<br>Prepare for International University Education.</h4>\r\n\r\n<p>The <strong>Portfolio Pathway Programme</strong>, developed by <strong>MAA – Magic Arts &amp; Architecture Education</strong>, is a specialised educational pathway for students aged 15–18 who aspire to pursue creative disciplines at universities in Germany, across Europe and Asia.</p>\r\n\r\n<p>The programme combines foundational Art &amp; Design education at MAA with advanced Portfolio Development delivered in academic collaboration with a strategic Art &amp; Design education partner in Germany.</p>\r\n\r\n<p>Guided by the philosophy <em>“ONE STUDENT. ONE DIRECTION.”</em>, the programme encourages students to discover their individual strengths, develop independent creative thinking and progressively build a personal portfolio aligned with their intended field of study.</p>\r\n\r\n<h3 style=\"color: #191919; margin-top: 35px; border-left: 4px solid #FFCB00; padding-left: 12px;\">TWO STAGES. ONE CREATIVE PATHWAY.</h3>\r\n\r\n<div style=\"background: #fafafa; border: 1px solid #e9ecef; border-radius: 8px; padding: 22px; margin: 25px 0;\">\r\n\t<h3 style=\"color: #191919; margin-top: 0; font-weight: 700;\">01 | PRE-PORTFOLIO</h3>\r\n\t<h5 style=\"color: #555; font-weight: 600;\">Creative Foundation &amp; Exploration</h5>\r\n\t<p style=\"margin-bottom: 12px;\">\r\n\t\t<strong>Age Group:</strong> 15–16 years<br>\r\n\t\t<strong>Recommended Duration:</strong> 1–2 years, depending on each student\'s individual learning pathway.\r\n\t</p>\r\n\r\n\t<h5 style=\"margin-top: 18px; color: #333;\">Course Overview</h5>\r\n\t<p>Pre-Portfolio is a foundation-level programme designed for students interested in Architecture, Interior Architecture, Communication Design, Product Design, Illustration, Fashion Design, Photography, Digital Art and related creative disciplines.</p>\r\n\t<p>The programme provides opportunities for students to explore their creative potential, gain an understanding of different disciplines and develop essential artistic and design skills before progressing to advanced portfolio preparation.</p>\r\n\r\n\t<h5 style=\"margin-top: 18px; color: #333;\">Key Learning Areas</h5>\r\n\t<ul>\r\n\t\t<li>Principles of visual composition, colour theory, form, proportion and perspective.</li>\r\n\t\t<li>Sketching techniques, visual storytelling and creative idea communication.</li>\r\n\t\t<li>Observation, research, idea development and creative problem-solving.</li>\r\n\t\t<li>Exploration of materials, model-making, spatial design and product development.</li>\r\n\t\t<li>Introduction to digital art and cross-disciplinary creative practices.</li>\r\n\t\t<li>Practical individual and collaborative creative projects.</li>\r\n\t</ul>\r\n\r\n\t<h5 style=\"margin-top: 18px; color: #333;\">Learning Outcomes</h5>\r\n\t<p>Upon completing the Pre-Portfolio stage, students are expected to:</p>\r\n\t<ul>\r\n\t\t<li>Establish a foundation in Art &amp; Design relevant to their future creative interests.</li>\r\n\t\t<li>Develop essential research, visual communication and project-development skills.</li>\r\n\t\t<li>Build a collection of foundational creative projects (Foundation Creative Portfolio).</li>\r\n\t\t<li>Gain a clearer understanding of their individual strengths and potential areas of specialisation.</li>\r\n\t</ul>\r\n\t<p style=\"font-weight: 700; color: #333; margin-top: 15px; margin-bottom: 0;\">BUILD YOUR FOUNDATION. DISCOVER YOUR CREATIVE DIRECTION.</p>\r\n</div>\r\n\r\n<div style=\"background: #fafafa; border: 1px solid #e9ecef; border-radius: 8px; padding: 22px; margin: 25px 0;\">\r\n\t<h3 style=\"color: #191919; margin-top: 0; font-weight: 700;\">02 | PORTFOLIO DEVELOPMENT</h3>\r\n\t<h5 style=\"color: #555; font-weight: 600;\">International Creative Portfolio &amp; University Preparation</h5>\r\n\t<p style=\"margin-bottom: 12px;\">\r\n\t\t<strong>Age Group:</strong> 17–18 years<br>\r\n\t\t<strong>Recommended Duration:</strong> 6–12 months, depending on individual ability and the requirements of the intended field of study.<br>\r\n\t\t<strong>Learning Format:</strong> Blended Learning – Online &amp; In-Person.\r\n\t</p>\r\n\r\n\t<h5 style=\"margin-top: 18px; color: #333;\">Course Overview</h5>\r\n\t<p>Portfolio Development is an advanced programme designed to support students in developing a personalised creative portfolio for applications to international university degree programmes in Art, Design, Architecture and related disciplines.</p>\r\n\t<p>The programme is delivered by MAA in collaboration with a strategic Art &amp; Design education partner based in Germany, combining discipline-specific portfolio guidance, academic feedback from Germany-based instructors and ongoing learning support from MAA in Vietnam.</p>\r\n\r\n\t<h5 style=\"margin-top: 18px; color: #333;\">Key Learning Focus</h5>\r\n\t<ul>\r\n\t\t<li>Assessing students\' creative abilities, identifying their strengths and exploring suitable academic disciplines and university programmes.</li>\r\n\t\t<li>Developing creative portfolio projects through research, sketching, experimentation, critical thinking and problem-solving, with a focus on the student\'s intended discipline.</li>\r\n\t\t<li>Strengthening research methods, creative exploration and design development, with an emphasis on the creative process rather than solely on the final outcome.</li>\r\n\t\t<li>Developing students\' ability to explain their creative projects, communicate design ideas and prepare for portfolio presentations in accordance with the requirements of their target university programmes.</li>\r\n\t\t<li>Learning through German approaches to creative education, receiving professional feedback and progressively refining a portfolio that reflects each student\'s individual creative identity.</li>\r\n\t</ul>\r\n\r\n\t<h5 style=\"margin-top: 18px; color: #333;\">Learning Journey</h5>\r\n\t<p>The programme guides students through four key stages:</p>\r\n\t<ul>\r\n\t\t<li>Explore individual abilities, creative disciplines and academic goals.</li>\r\n\t\t<li>Research, experiment and develop original creative projects.</li>\r\n\t\t<li>Improve and strengthen portfolio work through individual feedback.</li>\r\n\t\t<li>Curate, organise and present a personalised application portfolio.</li>\r\n\t</ul>\r\n\r\n\t<h5 style=\"margin-top: 18px; color: #333;\">Learning Outcomes</h5>\r\n\t<ul>\r\n\t\t<li>Upon completing the programme, students are expected to develop a personalised portfolio that demonstrates their creative identity, research abilities, design thinking, project-development process and capacity to communicate their creative decisions.</li>\r\n\t\t<li>Portfolio development is informed by the requirements of students\' target university programmes. Specific admission criteria, portfolio expectations and submission formats vary between institutions.</li>\r\n\t</ul>\r\n\t<p style=\"font-weight: 700; color: #333; margin-top: 15px; margin-bottom: 0;\">FROM IDEAS TO APPLICATION.</p>\r\n</div>\r\n\r\n<h3 style=\"color: #191919; margin-top: 35px; border-left: 4px solid #FFCB00; padding-left: 12px;\">INTERNATIONAL ACADEMIC EXPERIENCE</h3>\r\n<h5 style=\"color: #444; font-weight: 600;\">Academic Tour – Germany &amp; Europe</h5>\r\n<p>As part of its broader Portfolio Development pathway, MAA plans to incorporate international academic experiences in collaboration with its education partner in Germany.</p>\r\n<p>The <strong>Academic Tour Programme</strong> offers students opportunities to explore international academic and creative environments, gain insights into disciplines such as Architecture, Interior Architecture, Communication Design, Product Design, Illustration, Fashion Design, Photography and Digital Art, and broaden their understanding of creative education in Germany and across Europe.</p>\r\n<p>These experiences are intended to help students connect academic exploration with real-world creative practices, deepen their understanding of their chosen disciplines and make more informed decisions about their future educational pathways.</p>\r\n<p><em>Academic Tours are organised according to programme schedules, with participation requirements and arrangements announced separately.</em></p>\r\n<p style=\"font-weight: 700; color: #333;\">BEYOND THE CLASSROOM. EXPLORE YOUR CREATIVE FUTURE.</p>\r\n\r\n<h3 style=\"color: #191919; margin-top: 35px; border-left: 4px solid #FFCB00; padding-left: 12px;\">CREATIVE DISCIPLINES</h3>\r\n<p>The Portfolio Pathway Programme supports students interested in pursuing the following creative fields:</p>\r\n<p style=\"font-weight: 600; color: #222; font-size: 15px; line-height: 1.8;\">\r\n\tArchitecture &bull; Interior Architecture &bull; Communication Design &bull; Product Design &bull; Illustration &bull; Fashion Design &bull; Photography &bull; Digital Art\r\n</p>\r\n<p><em>And other related Art, Design and creative disciplines.</em></p>\r\n\r\n<h3 style=\"color: #191919; margin-top: 35px; border-left: 4px solid #FFCB00; padding-left: 12px;\">START YOUR CREATIVE JOURNEY</h3>\r\n<h5 style=\"color: #444; font-weight: 600;\">More Than Portfolio Preparation. A Foundation for Your Creative Future.</h5>\r\n<p>At MAA, we believe that preparing for a creative future begins with understanding each student\'s individual potential, developing essential creative skills and building a strong foundation for further academic study.</p>\r\n<p>From foundational Art &amp; Design education to advanced discipline-specific Portfolio Development, MAA supports students as they explore their interests, develop their creative identities and prepare for international higher education opportunities.</p>\r\n\r\n<div style=\"background: #fff9e6; border: 1px solid #ffe082; border-radius: 8px; padding: 22px; margin: 30px 0; text-align: center;\">\r\n\t<h4 style=\"color: #b78103; margin-bottom: 12px; font-weight: 700;\">REGISTER FOR A FREE INITIAL PROGRAMME ORIENTATION &amp; CONSULTATION</h4>\r\n\t<p style=\"margin-bottom: 15px;\">\r\n\t\t<a href=\"https://forms.gle/9cdFLfrhnzR7mUb77\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"background: #FFCB00; color: #191919; padding: 12px 28px; font-weight: 700; border-radius: 4px; display: inline-block; text-decoration: none; font-size: 15px;\">REGISTER HERE &rarr;</a>\r\n\t</p>\r\n\t<p style=\"font-size: 13px; color: #666; margin-bottom: 0;\">Link: <a href=\"https://forms.gle/9cdFLfrhnzR7mUb77\" target=\"_blank\" rel=\"noopener noreferrer\">https://forms.gle/9cdFLfrhnzR7mUb77</a></p>\r\n</div>\r\n\r\n<p style=\"text-align: center; color: #777; margin-top: 35px; border-top: 1px solid #eee; padding-top: 20px;\">\r\n\t<strong>MAA – MAGIC ARTS &amp; ARCHITECTURE EDUCATION</strong><br>\r\n\t<em>Your Future, Your Imagination.</em>\r\n</p>',

    `eng_ccontent` = '<p style=\"text-align:center; margin-bottom: 25px;\">\r\n\t<img src=\"/fileman/Uploads/programs/pd1.jpg\" alt=\"PORTFOLIO PATHWAY PROGRAM\" style=\"max-width:100%; height:auto; border-radius: 6px; box-shadow: 0 4px 15px rgba(0,0,0,0.1); margin: 0 auto; display: block;\">\r\n</p>\r\n\r\n<div class=\"program-detail-header\" style=\"margin-bottom: 25px; border-bottom: 2px solid #FFCB00; padding-bottom: 15px;\">\r\n\t<h2 style=\"color: #191919; margin-bottom: 5px; font-weight: 700;\">PORTFOLIO PATHWAY PROGRAMME</h2>\r\n\t<h4 style=\"color: #555; font-weight: 600; margin-bottom: 8px;\">Pre-Portfolio &amp; International Portfolio Development</h4>\r\n\t<p style=\"color: #777; font-size: 15px; margin-bottom: 8px;\"><strong>Ages 15–18</strong> | Personalised Creative Education Pathway</p>\r\n\t<p style=\"font-weight: 700; color: #d39e00; letter-spacing: 0.5px; text-transform: uppercase;\">YOUR DREAM DEGREE. YOUR INDIVIDUAL PORTFOLIO.</p>\r\n</div>\r\n\r\n<h4 style=\"color: #191919;\">Discover Your Potential. Develop Your Creative Identity.<br>Prepare for International University Education.</h4>\r\n\r\n<p>The <strong>Portfolio Pathway Programme</strong>, developed by <strong>MAA – Magic Arts &amp; Architecture Education</strong>, is a specialised educational pathway for students aged 15–18 who aspire to pursue creative disciplines at universities in Germany, across Europe and Asia.</p>\r\n\r\n<p>The programme combines foundational Art &amp; Design education at MAA with advanced Portfolio Development delivered in academic collaboration with a strategic Art &amp; Design education partner in Germany.</p>\r\n\r\n<p>Guided by the philosophy <em>“ONE STUDENT. ONE DIRECTION.”</em>, the programme encourages students to discover their individual strengths, develop independent creative thinking and progressively build a personal portfolio aligned with their intended field of study.</p>\r\n\r\n<h3 style=\"color: #191919; margin-top: 35px; border-left: 4px solid #FFCB00; padding-left: 12px;\">TWO STAGES. ONE CREATIVE PATHWAY.</h3>\r\n\r\n<div style=\"background: #fafafa; border: 1px solid #e9ecef; border-radius: 8px; padding: 22px; margin: 25px 0;\">\r\n\t<h3 style=\"color: #191919; margin-top: 0; font-weight: 700;\">01 | PRE-PORTFOLIO</h3>\r\n\t<h5 style=\"color: #555; font-weight: 600;\">Creative Foundation &amp; Exploration</h5>\r\n\t<p style=\"margin-bottom: 12px;\">\r\n\t\t<strong>Age Group:</strong> 15–16 years<br>\r\n\t\t<strong>Recommended Duration:</strong> 1–2 years, depending on each student\'s individual learning pathway.\r\n\t</p>\r\n\r\n\t<h5 style=\"margin-top: 18px; color: #333;\">Course Overview</h5>\r\n\t<p>Pre-Portfolio is a foundation-level programme designed for students interested in Architecture, Interior Architecture, Communication Design, Product Design, Illustration, Fashion Design, Photography, Digital Art and related creative disciplines.</p>\r\n\t<p>The programme provides opportunities for students to explore their creative potential, gain an understanding of different disciplines and develop essential artistic and design skills before progressing to advanced portfolio preparation.</p>\r\n\r\n\t<h5 style=\"margin-top: 18px; color: #333;\">Key Learning Areas</h5>\r\n\t<ul>\r\n\t\t<li>Principles of visual composition, colour theory, form, proportion and perspective.</li>\r\n\t\t<li>Sketching techniques, visual storytelling and creative idea communication.</li>\r\n\t\t<li>Observation, research, idea development and creative problem-solving.</li>\r\n\t\t<li>Exploration of materials, model-making, spatial design and product development.</li>\r\n\t\t<li>Introduction to digital art and cross-disciplinary creative practices.</li>\r\n\t\t<li>Practical individual and collaborative creative projects.</li>\r\n\t</ul>\r\n\r\n\t<h5 style=\"margin-top: 18px; color: #333;\">Learning Outcomes</h5>\r\n\t<p>Upon completing the Pre-Portfolio stage, students are expected to:</p>\r\n\t<ul>\r\n\t\t<li>Establish a foundation in Art &amp; Design relevant to their future creative interests.</li>\r\n\t\t<li>Develop essential research, visual communication and project-development skills.</li>\r\n\t\t<li>Build a collection of foundational creative projects (Foundation Creative Portfolio).</li>\r\n\t\t<li>Gain a clearer understanding of their individual strengths and potential areas of specialisation.</li>\r\n\t</ul>\r\n\t<p style=\"font-weight: 700; color: #333; margin-top: 15px; margin-bottom: 0;\">BUILD YOUR FOUNDATION. DISCOVER YOUR CREATIVE DIRECTION.</p>\r\n</div>\r\n\r\n<div style=\"background: #fafafa; border: 1px solid #e9ecef; border-radius: 8px; padding: 22px; margin: 25px 0;\">\r\n\t<h3 style=\"color: #191919; margin-top: 0; font-weight: 700;\">02 | PORTFOLIO DEVELOPMENT</h3>\r\n\t<h5 style=\"color: #555; font-weight: 600;\">International Creative Portfolio &amp; University Preparation</h5>\r\n\t<p style=\"margin-bottom: 12px;\">\r\n\t\t<strong>Age Group:</strong> 17–18 years<br>\r\n\t\t<strong>Recommended Duration:</strong> 6–12 months, depending on individual ability and the requirements of the intended field of study.<br>\r\n\t\t<strong>Learning Format:</strong> Blended Learning – Online &amp; In-Person.\r\n\t</p>\r\n\r\n\t<h5 style=\"margin-top: 18px; color: #333;\">Course Overview</h5>\r\n\t<p>Portfolio Development is an advanced programme designed to support students in developing a personalised creative portfolio for applications to international university degree programmes in Art, Design, Architecture and related disciplines.</p>\r\n\r\n\t<p>The programme is delivered by MAA in collaboration with a strategic Art &amp; Design education partner based in Germany, combining discipline-specific portfolio guidance, academic feedback from Germany-based instructors and ongoing learning support from MAA in Vietnam.</p>\r\n\r\n\t<h5 style=\"margin-top: 18px; color: #333;\">Key Learning Focus</h5>\r\n\t<ul>\r\n\t\t<li>Assessing students\' creative abilities, identifying their strengths and exploring suitable academic disciplines and university programmes.</li>\r\n\t\t<li>Developing creative portfolio projects through research, sketching, experimentation, critical thinking and problem-solving, with a focus on the student\'s intended discipline.</li>\r\n\t\t<li>Strengthening research methods, creative exploration and design development, with an emphasis on the creative process rather than solely on the final outcome.</li>\r\n\t\t<li>Developing students\' ability to explain their creative projects, communicate design ideas and prepare for portfolio presentations in accordance with the requirements of their target university programmes.</li>\r\n\t\t<li>Learning through German approaches to creative education, receiving professional feedback and progressively refining a portfolio that reflects each student\'s individual creative identity.</li>\r\n\t</ul>\r\n\r\n\t<h5 style=\"margin-top: 18px; color: #333;\">Learning Journey</h5>\r\n\t<p>The programme guides students through four key stages:</p>\r\n\t<ul>\r\n\t\t<li>Explore individual abilities, creative disciplines and academic goals.</li>\r\n\t\t<li>Research, experiment and develop original creative projects.</li>\r\n\t\t<li>Improve and strengthen portfolio work through individual feedback.</li>\r\n\t\t<li>Curate, organise and present a personalised application portfolio.</li>\r\n\t</ul>\r\n\r\n\t<h5 style=\"margin-top: 18px; color: #333;\">Learning Outcomes</h5>\r\n\t<ul>\r\n\t\t<li>Upon completing the programme, students are expected to develop a personalised portfolio that demonstrates their creative identity, research abilities, design thinking, project-development process and capacity to communicate their creative decisions.</li>\r\n\t\t<li>Portfolio development is informed by the requirements of students\' target university programmes. Specific admission criteria, portfolio expectations and submission formats vary between institutions.</li>\r\n\t</ul>\r\n\t<p style=\"font-weight: 700; color: #333; margin-top: 15px; margin-bottom: 0;\">FROM IDEAS TO APPLICATION.</p>\r\n</div>\r\n\r\n<h3 style=\"color: #191919; margin-top: 35px; border-left: 4px solid #FFCB00; padding-left: 12px;\">INTERNATIONAL ACADEMIC EXPERIENCE</h3>\r\n<h5 style=\"color: #444; font-weight: 600;\">Academic Tour – Germany &amp; Europe</h5>\r\n<p>As part of its broader Portfolio Development pathway, MAA plans to incorporate international academic experiences in collaboration with its education partner in Germany.</p>\r\n<p>The <strong>Academic Tour Programme</strong> offers students opportunities to explore international academic and creative environments, gain insights into disciplines such as Architecture, Interior Architecture, Communication Design, Product Design, Illustration, Fashion Design, Photography and Digital Art, and broaden their understanding of creative education in Germany and across Europe.</p>\r\n<p>These experiences are intended to help students connect academic exploration with real-world creative practices, deepen their understanding of their chosen disciplines and make more informed decisions about their future educational pathways.</p>\r\n<p><em>Academic Tours are organised according to programme schedules, with participation requirements and arrangements announced separately.</em></p>\r\n<p style=\"font-weight: 700; color: #333;\">BEYOND THE CLASSROOM. EXPLORE YOUR CREATIVE FUTURE.</p>\r\n\r\n<h3 style=\"color: #191919; margin-top: 35px; border-left: 4px solid #FFCB00; padding-left: 12px;\">CREATIVE DISCIPLINES</h3>\r\n<p>The Portfolio Pathway Programme supports students interested in pursuing the following creative fields:</p>\r\n<p style=\"font-weight: 600; color: #222; font-size: 15px; line-height: 1.8;\">\r\n\tArchitecture &bull; Interior Architecture &bull; Communication Design &bull; Product Design &bull; Illustration &bull; Fashion Design &bull; Photography &bull; Digital Art\r\n</p>\r\n<p><em>And other related Art, Design and creative disciplines.</em></p>\r\n\r\n<h3 style=\"color: #191919; margin-top: 35px; border-left: 4px solid #FFCB00; padding-left: 12px;\">START YOUR CREATIVE JOURNEY</h3>\r\n<h5 style=\"color: #444; font-weight: 600;\">More Than Portfolio Preparation. A Foundation for Your Creative Future.</h5>\r\n<p>At MAA, we believe that preparing for a creative future begins with understanding each student\'s individual potential, developing essential creative skills and building a strong foundation for further academic study.</p>\r\n<p>From foundational Art &amp; Design education to advanced discipline-specific Portfolio Development, MAA supports students as they explore their interests, develop their creative identities and prepare for international higher education opportunities.</p>\r\n\r\n<div style=\"background: #fff9e6; border: 1px solid #ffe082; border-radius: 8px; padding: 22px; margin: 30px 0; text-align: center;\">\r\n\t<h4 style=\"color: #b78103; margin-bottom: 12px; font-weight: 700;\">REGISTER FOR A FREE INITIAL PROGRAMME ORIENTATION &amp; CONSULTATION</h4>\r\n\t<p style=\"margin-bottom: 15px;\">\r\n\t\t<a href=\"https://forms.gle/9cdFLfrhnzR7mUb77\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"background: #FFCB00; color: #191919; padding: 12px 28px; font-weight: 700; border-radius: 4px; display: inline-block; text-decoration: none; font-size: 15px;\">REGISTER HERE &rarr;</a>\r\n\t</p>\r\n\t<p style=\"font-size: 13px; color: #666; margin-bottom: 0;\">Link: <a href=\"https://forms.gle/9cdFLfrhnzR7mUb77\" target=\"_blank\" rel=\"noopener noreferrer\">https://forms.gle/9cdFLfrhnzR7mUb77</a></p>\r\n</div>\r\n\r\n<p style=\"text-align: center; color: #777; margin-top: 35px; border-top: 1px solid #eee; padding-top: 20px;\">\r\n\t<strong>MAA – MAGIC ARTS &amp; ARCHITECTURE EDUCATION</strong><br>\r\n\t<em>Your Future, Your Imagination.</em>\r\n</p>'
WHERE `nid` = 28;

